-- Table structure for table `shared_art`
--

DROP TABLE IF EXISTS `shared_art`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shared_art` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `child_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `from_name` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_username` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_key` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_bytes` bigint NOT NULL,
  `model_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `owner_user_id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `picture` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `style` varchar(12) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_shared_art_key` (`item_key`,`created_at`),
  KEY `ix_shared_art_child` (`child_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
